,p_plug_template=>wwv_flow_imp.id(92844556009315187)
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT NUMPOLUNICO AS NO_POLIZA, IDPOLIZA AS CONSECUTIVO, FECINIVIG AS INICIO, FECFINVIG AS FIN,',
'LTRIM(RTRIM((TRANSLATE(OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE),'',       '',''  '')))) NOM_CONTRATANTE ,',
'(',
'            SELECT MAX(FECFINVIG)',
'            FROM FACTURAS',
'            WHERE IDPOLIZA = P.IDPOLIZA AND STSFACT = ''PAG''',
'          ) AS PAGADO_HASTA,',
'          FECRENOVACION AS FECHA_RENOVACION',
'FROM POLIZAS P',
'WHERE IDPOLIZA IN (',
'SELECT IDPOLIZA FROM COTIZACIONES',
'WHERE NUMCOTIZACIONREF LIKE ''%BANK%''',
'AND STSCOTIZACION=''POLEMI'')',
'AND FECFINVIG > SYSDATE',
'AND STSPOLIZA =''EMI''',
'ORDER BY FECRENOVACION ASC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
